<?php
require_once __DIR__ . '/../Config/database.php';
header('Content-Type: application/json; charset=utf-8');date_default_timezone_set('Asia/Jakarta');
function jd($ok,$message='',$data=[],$code=200){http_response_code($code);echo json_encode(array_merge(['success'=>$ok,'message'=>$message],$data),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
try{$pdo=(new Database())->connect();$id=(int)($_GET['customer_id']??0);if($id<=0)jd(false,'Customer tidak valid.',[],422);$s=$pdo->prepare('SELECT * FROM billing_customers WHERE id=?');$s->execute([$id]);$c=$s->fetch(PDO::FETCH_ASSOC);if(!$c)jd(false,'Pelanggan tidak ditemukan.',[],404);$s=$pdo->prepare("SELECT i.id,i.invoice_no,i.period,i.amount,i.due_date,i.status,i.paid_at,i.payment_method,i.notes FROM billing_invoices i WHERE i.customer_id=? ORDER BY i.period DESC,i.id DESC LIMIT 100");$s->execute([$id]);$inv=$s->fetchAll(PDO::FETCH_ASSOC);$sum=['invoice_count'=>count($inv),'billed'=>0,'paid'=>0,'unpaid'=>0,'overdue'=>0];foreach($inv as $i){$sum['billed']+=(float)$i['amount'];if($i['status']==='paid')$sum['paid']+=(float)$i['amount'];if($i['status']==='unpaid'){$sum['unpaid']+=(float)$i['amount'];if($i['due_date']<date('Y-m-d'))$sum['overdue']+=(float)$i['amount'];}}$active=false;$api='http://127.0.0.1/NetworkMonitor/api/pppoe.php?action=active';$raw=@file_get_contents($api);$j=json_decode($raw?:'',true);foreach(($j['active']??$j['data']??[]) as $x){if(($x['name']??$x['username']??'')===$c['pppoe_username']){$active=true;break;}}jd(true,'',['customer'=>$c,'invoices'=>$inv,'summary'=>$sum,'pppoe'=>['active'=>$active]]);}catch(Throwable $e){jd(false,$e->getMessage(),[],500);}
